pdf.css:
/* PDF do formulário demo. Tokens de cor de mockups/00-design-system.html; corpo 11/15,5 pt e
   margens de 18 mm (05-ui-ux.md §4.11). Source Sans Pro ainda não está embutida: títulos em Source Sans. */
:root {
  --obsidian-950: #120D0B;
  --on-dark: #F7F2EA;
  --ink-900: #1A1613;
  --ink-700: #3F3832;
  --ink-600: #5B534A;
  --line: #D8D0C5;
  --wine-700: #9B1C28;
  --gold-50: #FBF3DF;
  --gold-300: #EBCB8B;
  --gold-500: #B8863B;
  --gold-700: #7A5714;
}

@page {
  size: A4;
  margin: 18mm 18mm 22mm;
  @bottom-left {
    content: "Leadkit · Plano de ação personalizado";
    width: 70%;
    padding-top: 6pt;
    border-top: 0.5pt solid #D8D0C5;
    vertical-align: top;
    font: 8.5pt "Source Sans Pro";
    color: #5B534A;
  }
  @bottom-right {
    content: "Página " counter(page) " de " counter(pages);
    width: 30%;
    padding-top: 6pt;
    border-top: 0.5pt solid #D8D0C5;
    vertical-align: top;
    text-align: right;
    font: 8.5pt "Source Sans Pro";
    color: #5B534A;
  }
}

html {
  font-size: 11pt;
  line-height: 15.5pt;
  color: var(--ink-900);
  hyphens: manual; /* hífen automático entra como texto e atrapalha a busca no PDF */
  overflow-wrap: break-word;
}
body { margin: 0; }
p { margin: 0 0 6pt; orphans: 3; widows: 3; }
h1, h2 { margin: 0; font-weight: 700; break-after: avoid; }

.cover {
  padding: 22pt 24pt 20pt;
  margin-bottom: 8pt;
  border-radius: 10pt;
  /* brilho vinho da marca sobre obsidiana; paradas sólidas (sem alfa) imprimem igual em todo leitor */
  background: radial-gradient(farthest-corner at 100% 0%, #55161F 0%, #2E1015 35%, #120D0B 70%);
  color: var(--on-dark);
}
.cover::before {
  content: "";
  display: block;
  width: 30pt;
  height: 2.5pt;
  margin-bottom: 10pt;
  background: var(--gold-500);
}
.eyebrow {
  margin-bottom: 6pt;
  font-size: 8.5pt;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gold-300);
}
.cover h1 { font-size: 24pt; line-height: 28pt; margin-bottom: 10pt; color: #FFFFFF; }
.cover .meta { margin: 0; font-size: 10.5pt; color: rgba(247, 242, 234, 0.86); }
.cover .meta strong { font-weight: 600; color: #FFFFFF; }

h2 {
  margin: 18pt 0 8pt;
  padding-bottom: 4pt;
  border-bottom: 0.75pt solid var(--line);
  font-size: 13pt;
  line-height: 17pt;
  color: var(--wine-700);
}

/* Número em bloco inline (e não posicionado): o PDF continua na ordem de leitura do conteúdo. */
ol.actions { margin: 0; padding: 0; list-style: none; counter-reset: acao; }
ol.actions li { margin-bottom: 9pt; padding-left: 26pt; counter-increment: acao; }
ol.actions li::before {
  content: counter(acao);
  display: inline-block;
  width: 16pt;
  height: 16pt;
  margin-left: -26pt;
  margin-right: 10pt;
  border-radius: 8pt;
  background: var(--wine-700);
  color: #FFFFFF;
  font-size: 9pt;
  font-weight: 700;
  line-height: 16pt;
  text-align: center;
  vertical-align: 1pt;
}

.next {
  margin-top: 16pt;
  padding: 12pt 16pt 8pt;
  border-left: 3pt solid var(--gold-500);
  background: var(--gold-50);
  break-inside: avoid;
}
.next h2 {
  margin: 0 0 4pt;
  padding: 0;
  border: 0;
  font-size: 9pt;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gold-700);
}

.fineprint {
  margin-top: 20pt;
  font-size: 8.5pt;
  line-height: 12pt;
  color: var(--ink-600);
  break-before: avoid; /* o aviso não fica sozinho numa página */
}
